from django.db import migrations, models


def fill_status_at(apps, schema_editor):
    """الأوردرات القديمة: تاريخ التحصيل من حركة الخزنة بتاعته (أدق)، وإلا آخر تحديث"""
    Order = apps.get_model("trade", "OnlineOrder")
    CashEntry = apps.get_model("trade", "CashEntry")
    for o in Order.objects.filter(status__in=["collected", "returned"]):
        kind = "online" if o.status == "collected" else "online_return"
        e = CashEntry.objects.filter(online_order_id=o.pk, kind=kind).order_by("-created_at").first()
        Order.objects.filter(pk=o.pk).update(status_at=e.created_at if e else o.updated_at)


